import json

with open('json/posts.json', 'r') as f:
    data = json.load(f)

# Get slashnick's user ID
slashnick_id = 16

# Filter slashnick's posts and get AnswerCounts
slashnick_posts = []
for p in data['records']:
    if p.get('OwnerUserId') == slashnick_id:
        slashnick_posts.append({
            'Id': p.get('Id'),
            'AnswerCount': p.get('AnswerCount'),
            'Title': p.get('Title', '')
        })

print(f'Total posts by slashnick: {len(slashnick_posts)}')
for post in slashnick_posts:
    print(f"ID: {post['Id']}, AnswerCount: {post['AnswerCount']}, Title: {post['Title'][:50] if post['Title'] else 'N/A'}")

# Find post with highest AnswerCount (treating None as 0)
max_post = None
max_answers = -1
for post in slashnick_posts:
    ac = post['AnswerCount'] if post['AnswerCount'] is not None else 0
    if ac > max_answers:
        max_answers = ac
        max_post = post

if max_post:
    print(f'\nPost with most answers: ID={max_post["Id"]}, AnswerCount={max_post["AnswerCount"]}')
else:
    print('No posts found')

